# -*- coding: utf-8 --

from taf.rfrl.cbts.connections.rest_conn_vdu import GenericVDU
from robot.api import logger


class vDUOPE(GenericVDU):

    def get_vdu_sw_version_from_webem(self, conn_alias='default'):
        vdu_state = self.vdu.get_vdu_state_data(vdu_connection=conn_alias)
        return vdu_state['software_version']

    def get_vdu_mrbts_id_from_webem(self, use_m2m=True, conn_alias='default'):
        vdu_state = self.vdu.get_vdu_state_data(vdu_connection=conn_alias, use_m2m=use_m2m)
        return 'MRBTS-{}'.format(vdu_state['id'])

    def get_vdu_nrbts_id_from_webem(self, use_m2m=True, conn_alias='default'):
        vdu_state = self.vdu.get_vdu_state_data(vdu_connection=conn_alias, use_m2m=use_m2m)
        return 'NRBTS-{}'.format(vdu_state['nrbts_id'])

    def get_cells_number_from_vdu_webem(self, conn_alias='default'):
        cells_id_list = []
        cells_items = self.get_all_vdu_cells_statuses(conn_alias=conn_alias)

        for cell in cells_items:
            cells_id_list.append(cell['id'])
        return len(cells_id_list)

    def get_cells_id_list_from_vdu_webem(self, conn_alias='default'):
        cells_id_list = []
        cells_items = self.get_all_vdu_cells_statuses(conn_alias=conn_alias)

        for cell in cells_items:
            cells_id_list.append(cell['id'])
        return cells_id_list

    def get_all_vdu_cells_statuses(self, conn_alias='default'):
        cells_status = self.vdu.get_vdu_cells_status(vdu_connection=conn_alias)
        logger.info('******** All of the cells information are as below\n{}'.format(cells_status))
        return cells_status

    def get_rmod_status(self, conn_alias='default'):
        rmod_status = self.vdu.get_rmods_status(vdu_connection=conn_alias)
        return rmod_status
